import { expect, test } from 'bun:test';
import { REDACTED, redactSecrets } from './redact.ts';

const r = (s: string) => redactSecrets(s).text;

test('known token formats are replaced wherever they appear', () => {
  const tokens = [
    'sk-ant-api03-' + 'x1'.repeat(20),
    '[cedia:redacted]',
    'ghp_' + 'a1'.repeat(18),
    'github_pat_' + 'B2'.repeat(20),
    '[cedia:redacted]',
    '[cedia:redacted]',
    'AIza' + 'c'.repeat(35),
    '[cedia:redacted]',
  ];
  for (const t of tokens) expect(r(`value ${t} end`)).toBe(`value ${REDACTED} end`);
  expect(redactSecrets(tokens.join('\n')).count).toBe(tokens.length);
});

test('a private key block goes whole, even when the output was cut before its end', () => {
  expect(r('a\n[cedia:redacted]\nz')).toBe(`a\n${REDACTED}\nz`);
  expect(r('[cedia:redacted]\nkeep me\n[cedia:redacted]';
  expect(redactSecrets(two)).toEqual({ text: `${REDACTED}\nkeep me\n${REDACTED}`, count: 2 });
});

test('dotenv, JSON, YAML and URL secrets keep their names', () => {
  expect(r('OPENAI_API_KEY=[cedia:redacted] DB_PASSWORD=changeme')).toBe(`OPENAI_API_KEY=${REDACTED}\nDEBUG=1\nexport DB_PASSWORD=${REDACTED}`);
  expect(r('{"api_key": "[cedia:redacted]", "name": "x"}')).toBe(`{"api_key": "${REDACTED}", "name": "x"}`);
  expect(r('secret = "[cedia:redacted]"')).toBe(`secret = "${REDACTED}"`);
  expect(r('DATABASE_URL=postgres://app:[cedia:redacted]@db:5432/x')).toBe(`DATABASE_URL=postgres://app:[cedia:redacted]@db:5432/x`);
});

test('code that only names a secret reads as written', () => {
  for (const line of [
    'password: hashPassword(input),',
    'password: password,',
    'const token = getToken();',
    'const apiKey = process.env.OPENAI_API_KEY',
    'api_key = os.environ["KEY"]',
    'max_tokens: 1000',
    'MAX_TOKENS=4096',
    'tokenizer = "bert-base-uncased"',
    'pip install scikit-learn sk-learn-and-more-words',
    `KEY=${REDACTED}`,
  ])
    expect([line, redactSecrets(line).count]).toEqual([line, 0]);
});
